export function statusLabel(running) {
  return (running ? (() => { return "Stop"; })() : (() => { return "Start"; })());
}

export function statusMessage(running) {
  return (running ? (() => { return "System running"; })() : (() => { return "System stopped"; })());
}

export function initMessage(ok) {
  return (ok ? (() => { return "System initialized"; })() : (() => { return "Initialization failed"; })());
}

export function startFailureMessage() {
  return "Failed to start";
}

export function neuralContextOrPlaceholder(ctx) {
  return ((ctx === "") ? (() => { return "[No neural state available]"; })() : (() => { return ctx; })());
}

export function queryEmptyMessage() {
  return "Please enter a message";
}

export function responseOrFallback(resp) {
  return ((resp === "") ? (() => { return "No response received"; })() : (() => { return resp; })());
}

export function sanitizeQuery(raw) {
  return String(raw).trim();
}

export function isQueryNonEmpty(raw) {
  return (sanitizeQuery(raw) !== "");
}

